export type RuleValueType = 'numeric' | 'text' | 'boolean' | 'select' | 'json'
export type SalaryMode = 'days_prorated_mode' | 'orders_based_mode' | 'hybrid_mode_placeholder'
export type OrdersPolicy = 'linear_order_rate_policy' | 'strict_target_salary_policy'

export interface RuleDefinition {
  key: string
  label: string
  labelAr: string
  group: string
  valueType: RuleValueType
  defaultValue: number | string | boolean | string[] // type widened on vendoring (required_sheets is a list)
  unit?: string
  options?: string[]
  min?: number
  max?: number
  helpText?: string
  displayOrder: number
}

