// Convert rule list to a flat key->value map (using defaults)
export function getDefaultRuleMap(): Record<string, number | string | boolean | string[]> {
  const map: Record<string, number | string | boolean | string[]> = {}
  for (const def of DEFAULT_RULE_DEFINITIONS) {
    map[def.key] = def.defaultValue
  }
  return map
}
